# ! [stable (feature = "futures_api" , since = "1.36.0")] use split_decls_genesis :: ourprelude :: * ; use crate :: ops ; use crate :: pin :: Pin ; use crate :: task :: { Context , Poll } ; #[doc = " A future represents an asynchronous computation, commonly obtained by use of"] #[doc = " [`async`]."] #[doc = ""] #[doc = " A future is a value that might not have finished computing yet. This kind of"] #[doc = " \"asynchronous value\" makes it possible for a thread to continue doing useful"] #[doc = " work while it waits for the value to become available."] #[doc = ""] #[doc = " # The `poll` method"] #[doc = ""] #[doc = " The core method of future, `poll`, *attempts* to resolve the future into a"] #[doc = " final value. This method does not block if the value is not ready. Instead,"] #[doc = " the current task is scheduled to be woken up when it's possible to make"] #[doc = " further progress by `poll`ing again. The `context` passed to the `poll`"] #[doc = " method can provide a [`Waker`], which is a handle for waking up the current"] #[doc = " task."] #[doc = ""] #[doc = " When using a future, you generally won't call `poll` directly, but instead"] #[doc = " `.await` the value."] #[doc = ""] #[doc = " [`async`]: ../../std/keyword.async.html"] #[doc = " [`Waker`]: crate::task::Waker"] #[doc (notable_trait)] #[doc (search_unbox)] #[must_use = "futures do nothing unless you `.await` or poll them"] #[stable (feature = "futures_api" , since = "1.36.0")] #[lang = "future_trait"] #[diagnostic :: on_unimplemented (label = "`{Self}` is not a future" , message = "`{Self}` is not a future")] pub trait Future { #[doc = " The type of value produced on completion."] #[stable (feature = "futures_api" , since = "1.36.0")] #[lang = "future_output"] type Output ; #[doc = " Attempts to resolve the future to a final value, registering"] #[doc = " the current task for wakeup if the value is not yet available."] #[doc = ""] #[doc = " # Return value"] #[doc = ""] #[doc = " This function returns:"] #[doc = ""] #[doc = " - [`Poll::Pending`] if the future is not ready yet"] #[doc = " - [`Poll::Ready(val)`] with the result `val` of this future if it"] #[doc = "   finished successfully."] #[doc = ""] #[doc = " Once a future has finished, clients should not `poll` it again."] #[doc = ""] #[doc = " When a future is not ready yet, `poll` returns `Poll::Pending` and"] #[doc = " stores a clone of the [`Waker`] copied from the current [`Context`]."] #[doc = " This [`Waker`] is then woken once the future can make progress."] #[doc = " For example, a future waiting for a socket to become"] #[doc = " readable would call `.clone()` on the [`Waker`] and store it."] #[doc = " When a signal arrives elsewhere indicating that the socket is readable,"] #[doc = " [`Waker::wake`] is called and the socket future's task is awoken."] #[doc = " Once a task has been woken up, it should attempt to `poll` the future"] #[doc = " again, which may or may not produce a final value."] #[doc = ""] #[doc = " Note that on multiple calls to `poll`, only the [`Waker`] from the"] #[doc = " [`Context`] passed to the most recent call should be scheduled to"] #[doc = " receive a wakeup."] #[doc = ""] #[doc = " # Runtime characteristics"] #[doc = ""] #[doc = " Futures alone are *inert*; they must be *actively* `poll`ed for the"] #[doc = " underlying computation to make progress, meaning that each time the"] #[doc = " current task is woken up, it should actively re-`poll` pending futures"] #[doc = " that it still has an interest in."] #[doc = ""] #[doc = " Having said that, some Futures may represent a value that is being"] #[doc = " computed in a different task. In this case, the future's underlying"] #[doc = " computation is simply acting as a conduit for a value being computed"] #[doc = " by that other task, which will proceed independently of the Future."] #[doc = " Futures of this kind are typically obtained when spawning a new task into an"] #[doc = " async runtime."] #[doc = ""] #[doc = " The `poll` function should not be called repeatedly in a tight loop --"] #[doc = " instead, it should only be called when the future indicates that it is"] #[doc = " ready to make progress (by calling `wake()`). If you're familiar with the"] #[doc = " `poll(2)` or `select(2)` syscalls on Unix it's worth noting that futures"] #[doc = " typically do *not* suffer the same problems of \"all wakeups must poll"] #[doc = " all events\"; they are more like `epoll(4)`."] #[doc = ""] #[doc = " An implementation of `poll` should strive to return quickly, and should"] #[doc = " not block. Returning quickly prevents unnecessarily clogging up"] #[doc = " threads or event loops. If it is known ahead of time that a call to"] #[doc = " `poll` may end up taking a while, the work should be offloaded to a"] #[doc = " thread pool (or something similar) to ensure that `poll` can return"] #[doc = " quickly."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " Once a future has completed (returned `Ready` from `poll`), calling its"] #[doc = " `poll` method again may panic, block forever, or cause other kinds of"] #[doc = " problems; the `Future` trait places no requirements on the effects of"] #[doc = " such a call. However, as the `poll` method is not marked `unsafe`,"] #[doc = " Rust's usual rules apply: calls must never cause undefined behavior"] #[doc = " (memory corruption, incorrect use of `unsafe` functions, or the like),"] #[doc = " regardless of the future's state."] #[doc = ""] #[doc = " [`Poll::Ready(val)`]: Poll::Ready"] #[doc = " [`Waker`]: crate::task::Waker"] #[doc = " [`Waker::wake`]: crate::task::Waker::wake"] #[lang = "poll"] #[stable (feature = "futures_api" , since = "1.36.0")] fn poll (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Self :: Output > ; } #[stable (feature = "futures_api" , since = "1.36.0")] impl < F : ? Sized + Future + Unpin > Future for & mut F { type Output = F :: Output ; fn poll (mut self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Self :: Output > { F :: poll (Pin :: new (& mut * * self) , cx) } } #[stable (feature = "futures_api" , since = "1.36.0")] impl < P > Future for Pin < P > where P : ops :: DerefMut < Target : Future > , { type Output = < < P as ops :: Deref > :: Target as Future > :: Output ; fn poll (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Self :: Output > { < P :: Target as Future > :: poll (self . as_deref_mut () , cx) } }